def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Copy the complete reference bar color across the incomplete bar.
    colors = {row[0] for row in grid if row[0] != 0 and all(x == row[0] for x in row)}
    for r, row in enumerate(grid):
        for color in colors:
